  // live issues are counted the way a single creation counts them.
  const sourceIssues = input.includeIssues
    ? await listLiveIssues(input.orgId, source.id)
    : [];
  const requested = input.includeIssues
    ? Math.max(
        sourceIssues.length,
        await issueRepo.countIssues(input.orgId, source.id),
      )
    : 0;
  if (
    requested > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, requested)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}: cloning ${requested} issues from ${source.key} exceeds the per-project limit`,
    );
  }

  const clone = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

