  // default status, unassigned, unlinked, renumbered from 1 in source order.
  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  const copies: Issue[] = [];
  for (const issue of sourceIssues) {
    copies.push(
      await issueRepo.insertIssue(
        {
          orgId: input.orgId,
          projectId: clone.id,
          title: issue.title,
          description: issue.description,
          status,
          priority: issue.priority,
          assigneeId: null,
          parentId: null,
          estimate: issue.estimate,
          dueAt: issue.dueAt,
          labelIds: [...issue.labelIds],
        },
        actor.userId,
        copies.length + 1,
