/**
 * Every live issue of a project, in issue-number order. The repository only
 * serves pages, so this follows the cursor to the end.
 */
async function listLiveIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const byId = new Map<string, Issue>();
  let cursor: string | null = null;

  do {
    const page: Page<Issue> = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: ISSUE_PAGE_SIZE,
      cursor,
    });

    const before = byId.size;
    for (const issue of page.items) byId.set(issue.id, issue);

    // A cursor that yields nothing new would loop forever; stop instead.
    cursor = byId.size > before ? page.nextCursor : null;
  } while (cursor !== null);

  return [...byId.values()].sort((a, b) => a.number - b.number);
}

