    expect(src).toHaveLength(130);
    expect(src[0]).toMatchObject({ status: "in_progress", assigneeId: t.userIds.admin, number: 1 });
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.status).toBe("paused");

    expect(cloned).toHaveLength(1);
    expect(cloned[0]).toMatchObject({ orgId: t.org.id, actorId: t.userIds.member, projectId: clone.id, sourceProjectId: t.project.id, issuesCopied: 129 });
    expect(created).toHaveLength(0);
    expect(issueCreated).toHaveLength(0);
