    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({ action: "project.cloned", actorId: t.userIds.member, subjectKind: "project", subjectId: clone.id, projectId: clone.id, metadata: { sourceProjectId: t.project.id, issuesCopied: 129 } });
    expect((await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null })).total).toBe(1);

    const usageAfter = await usageRepo.getUsage(t.org.id);
